import{_ as t,o as e,c as s,a5 as r}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Rapports & tableau de bord","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/12-reports.md","filePath":"generated/modules/12-reports.md","lastUpdated":null}'),d={name:"modules/12-reports.md"};function n(o,a,i,p,l,c){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="rapports-tableau-de-bord" tabindex="-1">Rapports &amp; tableau de bord <a class="header-anchor" href="#rapports-tableau-de-bord" aria-label="Permalink to &quot;Rapports &amp; tableau de bord&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 3 · <a href="/VendoraSystem-docs/specs/12-reports">spécification complète</a></span></p><p>Rapports calculés côté serveur à partir des événements synchronisés : tableau de bord, ventes, marges, stock, caisse, pourboires, anti-fraude, multi-magasins et exports comptables. Le back-office expose déjà les alertes d&#39;intégrité, la latence des caisses, l&#39;archive des Z (avec PDF), les sessions de caisse avec X serveur, la page Service, les pourboires, le rapprochement fournisseur et le tableau anti-fraude (règles à seuils, alertes avec preuves, acquittement motivé). Lot 3.10 : KPI du jour et comparaisons, fraîcheur des données, rapports de ventes par dimension et marges au coût mémorisé, tableau de bord condensé sur les caisses ; rapports de stock, seuils réglables par magasin, ventes par type, export du détail en arrière-plan et récapitulatif quotidien par email. Lot 3.11c : comparaison et classement des magasins. Lot 3.12 : journaux comptables et FEC. Restent le e-reporting B2C (bloqué) et El Fatoora (phase 4).</p><div class="kpis"><div><b>24</b><span>faites</span></div><div><b>5</b><span>partielles</span></div><div><b>1</b><span>à faire</span></div><div><b>1</b><span>bloquées</span></div></div><h2 id="tableau-de-bord" tabindex="-1">Tableau de bord <a class="header-anchor" href="#tableau-de-bord" aria-label="Permalink to &quot;Tableau de bord&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Alertes d&#39;intégrité</strong><br><span class="muted">Voir par magasin, sur le tableau de bord, toutes les anomalies détectées par les projections (chaîne des Z, scellement des ventes, approbations falsifiées, erreurs de projection, rapprochements fournisseur, verrouillages PIN, imprimante cuisine), avec total, compteur par type et 20 dernières alertes datées.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td></td><td>2.23, 2.24, 2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a></td></tr><tr><td><strong>Latence des caisses</strong><br><span class="muted">Suivre au back-office les temps de réponse réels des caisses (p50 / p95 / max par action et par appareil, badge hors budget de 100 ms), remontés automatiquement après chaque synchronisation.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td></td><td>1.x, 2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-ios">📷</a></td></tr><tr><td><strong>KPI du jour et comparaisons</strong><br><span class="muted">Afficher le CA du jour, le nombre de tickets, le panier moyen et la marge, comparés à J-1 et J-7, avec la courbe du CA par heure, le top produits et les sessions ouvertes.<br><i>Lot 3.10 : panneau « Aujourd&#39;hui » du tableau de bord — CA, tickets, panier moyen, marge du jour (fuseau du magasin), évolutions vs la même plage d&#39;hier et du même jour la semaine passée, CA par heure (J-7 en trait), top produits, sessions ouvertes ; « Tous les magasins » consolidé si même devise ; actualisation 60 s.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-05, RG-RPT-06, RG-RPT-07</td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a></td></tr><tr><td><strong>Indicateur « données à jour à HH:MM »</strong><br><span class="muted">Savoir si les chiffres affichés sont complets grâce à l&#39;horodatage du dernier événement intégré par magasin et à la liste des appareils en retard de synchronisation (&gt; 15 min).<br><i>Lot 3.10 : « Données à jour à HH:MM » par magasin (dernier fait des caisses), avertissement au-delà de 15 min avec les appareils non synchronisés récemment, sur le tableau de bord, les ventes et les marges.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-02, RG-RPT-03</td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a></td></tr></tbody></table><h2 id="caisse" tabindex="-1">Caisse <a class="header-anchor" href="#caisse" aria-label="Permalink to &quot;Caisse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Archive des rapports Z</strong><br><span class="muted">Consulter l&#39;historique séquentiel des Z de chaque caisse avec leur contenu figé (CA par mode, TVA, mouvements, pourboires, annulations, retours), le statut d&#39;intégrité de la chaîne et l&#39;empreinte SHA-256 recalculée par le navigateur.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-12</td><td>1.x, 2.9, 2.20</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a></td></tr><tr><td><strong>Export PDF du Z et des clôtures</strong><br><span class="muted">Télécharger depuis le back-office le PDF d&#39;un Z (rendu depuis le contenu archivé, empreinte et intégrité revérifiées) et le registre des clôtures fiscales J/M/A ; chaque export est tracé dans le journal d&#39;audit.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-17</td><td>2.19, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-export-pdf-z">📷</a></td></tr><tr><td><strong>Sessions de caisse et rapport X serveur</strong><br><span class="muted">Lister les sessions de caisse d&#39;un magasin (ouvertes et closes) et afficher pour chacune un rapport X calculé par le serveur, identique à celui de la caisse.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-12</td><td>2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Rapport X sur la caisse</strong><br><span class="muted">Éditer à tout moment un rapport X sans effet (CA, TVA, mouvements d&#39;espèces, théorique, pourboires), affiché et imprimé avec la mention « ne vaut pas clôture ».</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td></td><td>1.x, 2.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-x-ios">📷</a></td></tr><tr><td><strong>Écarts de caisse par caissier</strong><br><span class="muted">Agréger les écarts comptés / théoriques par caissier et par période avec code couleur, et filtrer la page Sessions.<br><i>Écarts cumulés par caissier dans le tableau anti-fraude (lot 3.9) ; lot R7 : filtres période / caissier et écarts par caissier sur la page Sessions de caisse.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-12</td><td>R7</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr></tbody></table><h2 id="restaurant-service" tabindex="-1">Restaurant &amp; service <a class="header-anchor" href="#restaurant-service" aria-label="Permalink to &quot;Restaurant &amp; service&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Page Service (additions)</strong><br><span class="muted">Suivre le service en cours et les additions closes : additions, couverts, CA des additions, ticket moyen, offerts hors CA, annulations dont celles après « prêt » (gaspillage), délai moyen envoi → prêt, détail de chaque addition.<br><i>Lot R7 : actualisation automatique toutes les 30 s (désactivable, heure de la dernière mise à jour) et export CSV de la liste affichée. Export PDF : avec l&#39;export générique des rapports (3.10).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td></td><td>2.11, 2.13, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-service-back-office">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-rattrapage-additions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr><tr><td><strong>Délais par poste de préparation</strong><br><span class="muted">Voir par poste les lignes routées, prêtes, le délai moyen envoi → prêt comparé au délai cible et les lignes en retard.<br><i>« En retard » n&#39;a pas de filtre de période propre (suit celui des indicateurs).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td></td><td>2.13</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-rattrapage-additions">📷</a></td></tr><tr><td><strong>Ventes par type sur place / à emporter</strong><br><span class="muted">Ventiler les ventes par type de commande quand le module tables est actif.<br><i>Lot 3.10 : onglet « Par type de vente » des rapports de ventes (vente directe / sur place / à emporter), via la commande rattachée à chaque ligne de vente (rattrapée depuis le journal d&#39;événements). Écart : onglet toujours affiché, « Vente directe » en commerce.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td></td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310b-rapports-stock-recap">📷</a></td></tr><tr><td><strong>Food-cost par plat</strong><br><span class="muted">Comparer le coût théorique (fiche technique × CMP) au coût réel constaté par plat, avec alerte de dérive au-delà d&#39;un seuil par magasin.<br><i>Livré au lot 3.14 : théorique contre réel par plat, écarts par ingrédient valorisés, dérive signalée.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-23</td><td>3.14</td><td><a href="/VendoraSystem-docs/preuves/2026-11-02-314-food-cost">📷</a></td></tr></tbody></table><h2 id="pourboires" tabindex="-1">Pourboires <a class="header-anchor" href="#pourboires" aria-label="Permalink to &quot;Pourboires&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rapport des pourboires</strong><br><span class="muted">Agréger les pourboires hors CA par salarié, par service ou par jour sur une période, avec parts espèces / carte et export CSV pour le registre de répartition.<br><i>Lot R7 : regroupement « par service » lisible (n° de session, caisse, date) et export PDF. Reste : bénéficiaire limité au vendeur connecté ou au pot commun.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-22</td><td>2.9, 2.14, R7</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-pourboires">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-clients-rapports">📷</a></td></tr></tbody></table><h2 id="paiements" tabindex="-1">Paiements <a class="header-anchor" href="#paiements" aria-label="Permalink to &quot;Paiements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rapprochement des paiements fournisseur</strong><br><span class="muted">Contrôler par magasin chaque intent de paiement (fournisseur, référence, montant, statut, montant remboursé) et son rapprochement avec la vente poussée : OK ou anomalie détaillée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td></td><td>2.10, 2.14, 2.16, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-paiement-fournisseur">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-connecteurs-paiement">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr></tbody></table><h2 id="ventes" tabindex="-1">Ventes <a class="header-anchor" href="#ventes" aria-label="Permalink to &quot;Ventes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rapports de ventes par dimension</strong><br><span class="muted">Analyser les ventes d&#39;une période par produit, catégorie, vendeur, appareil, mode de paiement ou heure, en HT ou TTC, avec graphique et tableau triable.<br><i>Lot 3.10 : projection <code>sale_lines</code> (moteur partagé rejoué : remise ticket répartie, TVA par ligne ; retours négatifs, annulations exclues ; rattrapage au démarrage) ; page « Rapports de ventes » par produit, catégorie, vendeur, appareil, paiement, heure, magasin ; TTC / HT ; préréglages et dates ; tri ; CSV et PDF.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-04, RG-RPT-05, RG-RPT-06, RG-RPT-07</td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a></td></tr></tbody></table><h2 id="marges" tabindex="-1">Marges <a class="header-anchor" href="#marges" aria-label="Permalink to &quot;Marges&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Marges au coût moyen pondéré</strong><br><span class="muted">Voir la marge par produit et catégorie au CMP mémorisé à la vente, filtrer les produits non rentables et isoler ceux sans coût d&#39;achat (« marge inconnue »).<br><i>Lot 3.10 : marge au coût mémorisé à la vente (CMP du magasin, à défaut prix d&#39;achat ; jamais recalculé), par produit ou catégorie, non rentables signalés et filtrables, section « marge inconnue » hors des taux ; CSV et PDF. Seuil « non rentable » réglable par magasin (page Réglages des rapports, 0 % par défaut, le plus strict en consolidé). Limite : les ventes reprises au rattrapage portent le coût du moment du rattrapage.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-08, RG-RPT-09</td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-310b-rapports-stock-recap">📷</a></td></tr></tbody></table><h2 id="stock" tabindex="-1">Stock <a class="header-anchor" href="#stock" aria-label="Permalink to &quot;Stock&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rapports de stock</strong><br><span class="muted">Obtenir la valorisation du stock à date, la rotation, les produits dormants, les pertes / casse par motif et les écarts d&#39;inventaire.<br><i>Lot 3.10 : page Rapports de stock par magasin — valeur à une date (quantités reconstruites depuis le journal × CMP actuel, à défaut prix d&#39;achat), rotation (vendu ÷ stock moyen), produits dormants (délai réglable par magasin, 60 j par défaut), pertes et vols par motif, écarts des inventaires validés ; CSV et PDF. Limite : pas d&#39;historique de CMP, la valeur passée utilise le coût actuel.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-10, RG-RPT-11</td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310b-rapports-stock-recap">📷</a></td></tr></tbody></table><h2 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rapports clients, fidélité et ardoise</strong><br><span class="muted">Consulter les top clients, les points émis / rachetés et l&#39;encours d&#39;ardoise par client, réservés aux rôles autorisés.<br><i>Lot R7 suite : page « Rapports clients » — clients actifs / revenus / nouveaux, part des ventes identifiées, meilleurs clients ; fidélité (points gagnés, utilisés, expirés, repris, encours) ; ardoises (dû à date, ancienneté, ventes à crédit, règlements, pertes, rappels) ; période au choix, CSV et PDF.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-19</td><td>R7</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r7-suite-canaux-rapports">📷</a></td></tr></tbody></table><h2 id="anti-fraude" tabindex="-1">Anti-fraude <a class="header-anchor" href="#anti-fraude" aria-label="Permalink to &quot;Anti-fraude&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Tableau anti-fraude à seuils</strong><br><span class="muted">Évaluer par caissier et par appareil des règles configurables (remises, annulations, tiroir hors vente, écarts récurrents, ventes hors heures) et afficher un score.<br><i>Six règles à seuils par magasin, réglées par l&#39;OWNER et historisées (chaque jour jugé avec les seuils en vigueur, chaque vente avec les horaires de son heure) ; tableau par caissier avec score 0–100, niveau et règle dominante, écarts d&#39;inventaire, pertes, retours sans ticket et dérogations au stock.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-13</td><td>3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-reliquats">📷</a></td></tr><tr><td><strong>Alertes anti-fraude et acquittement</strong><br><span class="muted">Recevoir une alerte au franchissement d&#39;un seuil, l&#39;acquitter ou la rejeter avec motif obligatoire, le tout tracé. Chaque preuve mène à son entrée du journal d&#39;audit (qui, quoi, motif, n° d&#39;entrée), rattachée à l&#39;événement synchronisé qui l&#39;a produite.<br><i>Alerte unique par règle, caissier et jour avec ses événements sources ; email aux responsables à la levée ; acquittement ou rejet avec motif obligatoire (400), alerte déjà traitée (409), audit.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-15</td><td>3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-reliquats">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-preuves-push">📷</a></td></tr><tr><td><strong>Drill-down vers le journal d&#39;audit</strong><br><span class="muted">Remonter d&#39;un indicateur à la liste des événements sources puis à l&#39;entrée d&#39;audit complète (qui, quoi, où, quand, motif).<br><i>Preuves des alertes anti-fraude reliées à leurs entrées d&#39;audit (lot 3.9) ; journal d&#39;audit global filtrable, drill-down par élément depuis une fiche (lot R8a).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-14</td><td>R8</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r8a-journal-inscription">📷</a></td></tr></tbody></table><h2 id="multi-magasins" tabindex="-1">Multi-magasins <a class="header-anchor" href="#multi-magasins" aria-label="Permalink to &quot;Multi-magasins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Consolidation et classement des magasins</strong><br><span class="muted">Comparer et classer les magasins du tenant (CA, tickets, panier moyen, marge, écarts), sans total mélangé entre devises.<br><i>Lot 3.10 : « Tous les magasins » consolidé quand la devise est la même, onglet « Par magasin ». Lot 3.11c : page de comparaison avec classement selon l&#39;indicateur, part du CA, évolution vs la période précédente, produit phare et fraîcheur, un tableau par devise.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-16</td><td>3.10, 3.11c</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-311c-comparaison-magasins">📷</a></td></tr></tbody></table><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Export CSV / PDF de tout rapport</strong><br><span class="muted">Exporter n&#39;importe quel rapport en CSV (; UTF-8 BOM) ou PDF (logo, période, fraîcheur) en respectant exactement les filtres actifs.<br><i>CSV des pourboires, des sessions, du service, des rapports clients, des ventes, des marges et des rapports de stock ; PDF des Z, des clôtures fiscales, des rapports clients, des pourboires, des ventes, des marges et du stock (lot 3.10). Export du détail des lignes de vente : immédiat jusqu&#39;à 50 000 lignes, au-delà préparé en arrière-plan puis téléchargeable depuis la page (liste des exports). Reste : logo du magasin sur les PDF.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td>RG-RPT-17</td><td>2.9, 2.19, R7, 3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-pourboires">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-export-pdf-z">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r7-suite-canaux-rapports">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-310b-rapports-stock-recap">📷</a></td></tr><tr><td><strong>Récapitulatif quotidien par email</strong><br><span class="muted">Recevoir chaque soir un email (CA, tickets, panier moyen, comparaisons, top 5, écarts, alertes) configurable par magasin ou consolidé.<br><i>Lot 3.10 : page Récapitulatif quotidien — activation, heure d&#39;envoi (heure du magasin), destinataires, magasins, email consolidé ou un par magasin ; contenu : CA et comparaisons J-1 / J-7, tickets, panier moyen, marge, top 5, écarts de caisse, alertes anti-fraude ouvertes, fraîcheur des données. Un envoi par jour, 3 tentatives, échecs visibles au back-office ; bouton « Envoyer un essai ». Envoi par le fournisseur d&#39;emails configuré (SMTP réel à choisir en production).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-18</td><td>3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-310b-rapports-stock-recap">📷</a></td></tr></tbody></table><h2 id="comptabilite-conformite" tabindex="-1">Comptabilité &amp; conformité <a class="header-anchor" href="#comptabilite-conformite" aria-label="Permalink to &quot;Comptabilité &amp; conformité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Journaux de ventes et d&#39;encaissements</strong><br><span class="muted">Générer les journaux comptables d&#39;une période avec ventilation de la TVA par taux et comptes paramétrables.<br><i>Lot 3.12 : page « Exports comptables » — journal des ventes (ventilation de la TVA par taux, ventes HT et TVA collectée) et journal des encaissements (un compte par moyen de paiement, espèces nettes du rendu), écritures de centralisation journalière par magasin toujours équilibrées, export CSV ; plan de comptes paramétrable (comptes par taux et par moyen de paiement, codes journaux). Reste : pourboires et mouvements d&#39;espèces.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-28</td><td>3.12</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-312-exports-comptables">📷</a></td></tr><tr><td><strong>Fichier des écritures comptables (FEC)</strong><br><span class="muted">Produire le FEC France par exercice (18 champs, nommage SIRENFECAAAAMMJJ) avec le module pays FR.<br><i>Lot 3.12 : FEC d&#39;un exercice civil (18 champs, tabulation, SIRENFECAAAAMMJJ.txt) avec les écritures de ventes et d&#39;encaissements ; SIREN saisi dans le plan de comptes ; refus expliqué sans SIREN ou pour un commerce hors euros. Exercice décalé et génération en arrière-plan à venir si nécessaire.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-RPT-29</td><td>3.12</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-312-exports-comptables">📷</a></td></tr><tr><td><strong>E-reporting B2C France</strong><br><span class="muted">Produire les agrégats journaliers par taux de TVA et suivre leur transmission par décades via une plateforme agréée (accusés, rejets, néant).<br><i>Phase 3 — bloqué par l&#39;extérieur (TODO-PHASE1 §3) : plateforme agréée partenaire à contractualiser (sandboxes iopole / B2Brouter).</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-RPT-24, RG-RPT-25, RG-RPT-26, RG-RPT-27</td><td></td><td></td></tr><tr><td><strong>Export El Fatoora (Tunisie)</strong><br><span class="muted">Émettre des factures XML TEIF signées TunTrust et transmises via TTN pour les profils SERVICE / B2G.<br><i>Phase 4, optionnel.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-RPT-30</td><td></td><td></td></tr></tbody></table><h2 id="consultation-mobile" tabindex="-1">Consultation mobile <a class="header-anchor" href="#consultation-mobile" aria-label="Permalink to &quot;Consultation mobile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Tableau de bord mobile en lecture seule</strong><br><span class="muted">Sur la caisse ou le téléphone de salle, un responsable (MANAGER+) consulte en lecture seule, hors ligne compris (« Consulté à HH:MM — hors ligne »), les alertes anti-fraude (statut et motif du traitement au back-office), les passages sous le seuil de stock et les écarts de caisse à la clôture au-delà du seuil. Il en reçoit une notification système, une seule fois ; le caissier jamais. Toucher la notification ouvre l&#39;écran « Alertes ». Chaque alerte réveille aussi les appareils qui ont enregistré un jeton FCM / APNs (envoi simulé tant que les identifiants Firebase et Apple ne sont pas fournis). Le dashboard condensé (CA du jour, tickets) reste à faire.<br><i>Alertes (lot 3.9) ; lot 3.10 : tableau de bord condensé dans l&#39;écran « Alertes » des responsables — CA du jour, tickets, panier moyen, évolutions, top 3, relus à l&#39;ouverture (jeton de l&#39;appareil) et gardés hors ligne avec « consulté à HH:MM — hors ligne » (Android, iOS). Reste : push distant réel FCM / APNs (identifiants à fournir).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td></td><td>3.9, 3.10</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude-preuves-push">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-310-rapports-ventes">📷</a></td></tr></tbody></table><h2 id="socle" tabindex="-1">Socle <a class="header-anchor" href="#socle" aria-label="Permalink to &quot;Socle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Projections reconstructibles depuis les événements</strong><br><span class="muted">Garantir que les agrégats serveur se reconstruisent à l&#39;identique depuis l&#39;event_log (rattrapage au démarrage, idempotent).<br><i>Rattrapage fait pour les additions, pourboires, rapprochement fournisseur, sessions de caisse et lignes de vente (lot 3.10) ; SalesRollup et test CI « purge puis recalcul identique » restent à faire.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-RPT-20</td><td>2.13, 2.14, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-rattrapage-additions">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Logo du magasin sur les PDF ; historique du CMP pour une valorisation passée exacte.</li><li>Récap email quotidien : fournisseur SMTP réel à choisir en production.</li><li>E-reporting B2C (bloqué par la plateforme agréée) ; El Fatoora en phase 4 ; écritures des pourboires et des mouvements d&#39;espèces.</li><li>Consultation mobile : push distant réel FCM / APNs (identifiants Firebase et clé APNs Apple à fournir).</li></ul>',36)])])}const b=t(d,[["render",n]]);export{h as __pageData,b as default};
